func statusClass(s string) string {
	switch strings.TrimSpace(s) {
	case "??", "A":
		return "ok"
	case "D":
		return "err"
	}
	return "warn"
}

func diffClass(line string) string {
	switch {
	case strings.HasPrefix(line, "+++"), strings.HasPrefix(line, "---"):
		return "dim"
	case strings.HasPrefix(line, "+"):
		return "add"
	case strings.HasPrefix(line, "-"):
		return "del"
	case strings.HasPrefix(line, "@@"):
		return "hunk"
	case strings.HasPrefix(line, "diff "), strings.HasPrefix(line, "index "):
		return "dim"
	}
	return ""
}

func urlQuery(s string) string {
	r := strings.NewReplacer("%", "%25", "&", "%26", "#", "%23", "+", "%2B", " ", "%20", "'", "%27", "?", "%3F")
	return r.Replace(s)
}

func explorerParent(dir string) string {
	parent := pathpkg.Dir(dir)
	if parent == "." {
		return ""
	}
	return parent
}

func explorerPath(d ExplorerData) string {
	if d.Dir == "" {
		return d.Project.Name + "/"
	}
	return d.Project.Name + "/" + d.Dir
}

